import{_ as a,H as d,f as r,i as e}from"./chunks/framework.nyB-Xt5O.js";const u=JSON.parse('{"title":"BI 岗位全景图","description":"","frontmatter":{},"headers":[],"relativePath":"career/cd-1-overview.md","filePath":"career/cd-1-overview.md","lastUpdated":1779798726000}'),n={name:"career/cd-1-overview.md"};function o(l,t,s,i,h,c){return d(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="bi-岗位全景图" tabindex="-1">BI 岗位全景图 <a class="header-anchor" href="#bi-岗位全景图" aria-label="Permalink to &quot;BI 岗位全景图&quot;">​</a></h1><blockquote><p>数据分析与 BI 领域有哪些岗位？各岗位做什么、需要什么技能、天花板在哪？本文帮你梳理清楚。</p></blockquote><h2 id="五大岗位概览" tabindex="-1">五大岗位概览 <a class="header-anchor" href="#五大岗位概览" aria-label="Permalink to &quot;五大岗位概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>岗位</th><th>核心职责</th><th>主要产出</th><th>常用工具</th></tr></thead><tbody><tr><td>BI 分析师 (BI Analyst)</td><td>报表开发、看板维护、临时取数</td><td>数据看板、周期性报告</td><td>SQL + Tableau/Power BI + Excel</td></tr><tr><td>数据分析师 (Data Analyst)</td><td>业务问题分析、AB 实验、增长分析</td><td>分析报告、策略建议</td><td>SQL + Python/R + BI 工具</td></tr><tr><td>数据运营 (Data Operations)</td><td>日常数据监控、活动效果评估、渠道分析</td><td>运营日报、活动复盘</td><td>Excel + SQL + 公司内部平台</td></tr><tr><td>数据产品经理 (Data Product Manager)</td><td>BI 平台设计、数据产品规划、埋点规范</td><td>PRD、产品路线图</td><td>Axure/Figma + SQL + 项目管理工具</td></tr><tr><td>数据工程师 (Data Engineer)</td><td>数仓建设、ETL 管道、数据质量保障</td><td>数据仓库、数据平台</td><td>SQL + Spark/Flink + Airflow + Cloud</td></tr></tbody></table><h2 id="岗位详细解析" tabindex="-1">岗位详细解析 <a class="header-anchor" href="#岗位详细解析" aria-label="Permalink to &quot;岗位详细解析&quot;">​</a></h2><h3 id="bi-分析师-bi-analyst" tabindex="-1">BI 分析师（BI Analyst） <a class="header-anchor" href="#bi-分析师-bi-analyst" aria-label="Permalink to &quot;BI 分析师（BI Analyst）&quot;">​</a></h3><ul><li><strong>职责</strong>：负责公司级报表体系和看板的搭建与维护，响应业务方的临时取数需求，确保数据准确及时。</li><li><strong>核心技能</strong>：SQL（窗口函数、复杂 join、查询优化）+ BI 工具（Tableau/Power BI/Metabase）+ 业务理解。</li><li><strong>常见场景</strong>：搭建销售日报、财务月报、运营核心指标看板；排查报表数据不一致的原因。</li><li><strong>天花板</strong>：如果止步于&quot;接需求画报表&quot;，容易被工具取代；向上需要具备分析思维，从&quot;做什么报表&quot;走向&quot;业务需要什么指标&quot;。</li></ul><h3 id="数据分析师-data-analyst" tabindex="-1">数据分析师（Data Analyst） <a class="header-anchor" href="#数据分析师-data-analyst" aria-label="Permalink to &quot;数据分析师（Data Analyst）&quot;">​</a></h3><ul><li><strong>职责</strong>：主动发现业务问题，通过数据分析驱动决策，通常深度参与产品迭代和运营策略。</li><li><strong>核心技能</strong>：SQL + Python（pandas、numpy、scipy）+ 统计学（假设检验、回归分析）+ AB 实验设计 + 业务洞察。</li><li><strong>常见场景</strong>：评估新功能上线效果、分析用户流失原因、搭建业务指标体系。</li><li><strong>天花板</strong>：对业务理解深度要求高，如果停留在&quot;描述性分析&quot;层面，价值有限；进阶方向是数据科学或策略产品方向。</li></ul><h3 id="数据运营-data-operations" tabindex="-1">数据运营（Data Operations） <a class="header-anchor" href="#数据运营-data-operations" aria-label="Permalink to &quot;数据运营（Data Operations）&quot;">​</a></h3><ul><li><strong>职责</strong>：偏业务侧的数据支持，负责日常运营数据的追踪、活动效果评估、渠道 ROI 分析等。</li><li><strong>核心技能</strong>：Excel（透视表、vlookup）+ SQL（基础查询）+ 业务理解 + 沟通表达。</li><li><strong>常见场景</strong>：每日更新业务日报、分析各渠道获客成本、评估大促活动 ROI。</li><li><strong>天花板</strong>：如果只做数据搬运，成长空间有限；向分析方向转型需要补充统计学和编程能力。</li></ul><h3 id="数据产品经理-data-product-manager" tabindex="-1">数据产品经理（Data Product Manager） <a class="header-anchor" href="#数据产品经理-data-product-manager" aria-label="Permalink to &quot;数据产品经理（Data Product Manager）&quot;">​</a></h3><ul><li><strong>职责</strong>：规划数据类产品（BI 平台、标签系统、埋点平台、A/B 测试平台），输出 PRD，推动跨团队落地。</li><li><strong>核心技能</strong>：产品思维 + SQL（基本查询能力）+ 数据仓库常识 + 项目管理 + 沟通协调。</li><li><strong>常见场景</strong>：设计内部 BI 平台的功能迭代、梳理埋点规范文档、规划用户画像标签体系。</li><li><strong>天花板</strong>：需要同时懂数据技术和业务，相对稀缺；但需要持续跟进数据技术趋势，否则产品方案容易落后。</li></ul><h3 id="数据工程师-data-engineer" tabindex="-1">数据工程师（Data Engineer） <a class="header-anchor" href="#数据工程师-data-engineer" aria-label="Permalink to &quot;数据工程师（Data Engineer）&quot;">​</a></h3><ul><li><strong>职责</strong>：建设和管理数据基础设施，包括数仓建模、ETL 开发、数据管道运维、数据质量监控。</li><li><strong>核心技能</strong>：SQL（精通）+ 编程（Python/Java/Scala）+ 大数据框架（Spark/Flink/Hive）+ 调度工具（Airflow/Dagster）+ 云平台。</li><li><strong>常见场景</strong>：设计星型/雪花型模型、搭建实时数据管道、排查数据延迟或质量异常。</li><li><strong>天花板</strong>：技术门槛高，就业面广；但纯技术路线可能离业务越来越远，资深后选择管理或架构方向。</li></ul><h2 id="薪资与天花板对比" tabindex="-1">薪资与天花板对比 <a class="header-anchor" href="#薪资与天花板对比" aria-label="Permalink to &quot;薪资与天花板对比&quot;">​</a></h2><p>薪资水平因城市、行业、公司规模差异较大，以下为一线城市（北京/上海/深圳）的参考范围：</p><table tabindex="0"><thead><tr><th>岗位</th><th>0-2 年</th><th>3-5 年</th><th>5-8 年</th><th>8 年+</th><th>天花板瓶颈</th></tr></thead><tbody><tr><td>BI 分析师</td><td>8-15K</td><td>15-25K</td><td>25-35K</td><td>35-45K（管理岗）</td><td>容易陷入工具化，需要向分析转型</td></tr><tr><td>数据分析师</td><td>10-18K</td><td>18-30K</td><td>30-50K</td><td>50-80K+（专家/管理）</td><td>业务理解深度决定上限</td></tr><tr><td>数据运营</td><td>8-12K</td><td>12-20K</td><td>20-30K</td><td>30-40K（运营管理）</td><td>偏执行，需补技术能力转型</td></tr><tr><td>数据产品经理</td><td>12-18K</td><td>20-35K</td><td>35-55K</td><td>55-80K+（产品总监）</td><td>岗位稀少，需要懂技术又懂业务</td></tr><tr><td>数据工程师</td><td>12-20K</td><td>25-40K</td><td>40-60K</td><td>60-90K+（架构/管理）</td><td>技术迭代快，需要持续学习</td></tr></tbody></table><blockquote><p>注：薪资为税前月薪参考值，互联网行业通常高于传统行业，大厂会额外有股票/期权。</p></blockquote><h2 id="行业差异" tabindex="-1">行业差异 <a class="header-anchor" href="#行业差异" aria-label="Permalink to &quot;行业差异&quot;">​</a></h2><ul><li><strong>互联网</strong>：数据分析岗位最成熟，用户行为分析、AB 实验、增长分析是核心场景；薪资天花板最高，但也最卷。</li><li><strong>金融 / 银行</strong>：风控、反欺诈、客户画像为主；工作稳定，技术栈偏传统（Oracle + SAS），转型互联网需要更新技能。</li><li><strong>零售 / 消费品</strong>：进销存、会员分析、促销评估；节奏相对温和，数据量级较小，适合入门。</li><li><strong>制造业 / 传统企业</strong>：生产报表、供应链优化、质量分析；正在数字化转型中，岗位需求增加但薪资偏低。</li></ul><h2 id="如何选择方向" tabindex="-1">如何选择方向 <a class="header-anchor" href="#如何选择方向" aria-label="Permalink to &quot;如何选择方向&quot;">​</a></h2><p>没有&quot;最好&quot;的岗位，只有最适合你的切入方向：</p><table tabindex="0"><thead><tr><th>你的背景 / 偏好</th><th>推荐方向</th></tr></thead><tbody><tr><td>擅长沟通、喜欢跟业务打交道</td><td>数据分析师 / 数据运营</td></tr><tr><td>喜欢做产品、画原型、推动落地</td><td>数据产品经理</td></tr><tr><td>喜欢技术、写代码、搭系统</td><td>数据工程师</td></tr><tr><td>喜欢做报表、追求数据准确性</td><td>BI 分析师</td></tr><tr><td>想做数据科学、机器学习方向</td><td>数据分析师 → 数据科学家（进阶）</td></tr></tbody></table><h2 id="常见职业转型路径" tabindex="-1">常见职业转型路径 <a class="header-anchor" href="#常见职业转型路径" aria-label="Permalink to &quot;常见职业转型路径&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BI 分析师 ──→ 数据分析师 ──→ 资深分析师 / 数据科学家</span></span>
<span class="line"><span>      ↘              ↘</span></span>
<span class="line"><span>        数据运营 ────→ 业务运营 / 策略运营</span></span>
<span class="line"><span>              ↘</span></span>
<span class="line"><span>                数据产品经理 ──→ 数据产品总监</span></span>
<span class="line"><span>                      ↘</span></span>
<span class="line"><span>                        数据工程师 ──→ 数据架构师 / 技术管理</span></span></code></pre></div><p><strong>建议</strong>：入门阶段可以从 BI 分析师或数据运营切入，积累业务理解和数据 sense 后再横向迁移；擅长技术可直接走数据工程路线；产品感好的可以尝试数据产品经理方向。</p><blockquote><p>不管选哪条路，SQL 都是基本功，业务理解都是持久竞争力。先深耕一个方向，有余力再拓展周边能力。</p></blockquote>`,28)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
